 auto db=QSqlDatabase::addDatabase("QSQLITE","bom13");db.setDatabaseName(":memory:");check(db.open(),"SQLite available");QSqlQuery q(db);QStringList cols{"element_uuid TEXT","label TEXT","diagram_position INTEGER","position INTEGER"};for(QString suffix:{QString(),QString("_auxiliary1"),QString("_auxiliary2"),QString("_auxiliary3"),QString("_auxiliary4")})for(QString col:{"manufacturer","manufacturer_reference","designation","description","unity","quantity"})cols<<col+suffix+" TEXT";check(q.exec("CREATE TABLE element_nomenclature_view ("+cols.join(',')+")"),"BOM fixture schema");
